// every_pdf_we_issue_is_on_our_template.mjs — seat: accountant. 21 Sep 2026.
//
// The founder, 21 Sep 2026 (instructions 568, 569): "not a single pdf should be generated by our team
// unless its as per our template". The customer had been handed Stripe's own invoice PDF, which still
// read "due … Pay online" after the card was charged (customer audit 21 Sep, finding 5).
//
// The template is ONE renderer: supabase/functions/pdf_native/render.ts, wearing the letterhead in
// supabase/functions/_shared/doc_template.ts. A PDF is on the template when it comes out of that
// renderer (a POST to the pdf_native function, or renderPdf called directly). This check fails when
// code has any OTHER way to put a document in front of a person:
//
//   A. it makes PDF bytes itself: imports a PDF-writing library, or creates a PDF document object,
//      anywhere but pdf_native/;
//   B. it answers an HTTP request with a PDF body anywhere but pdf_native/;
//   C. it reads a Stripe-rendered document link off a Stripe object (the invoice file, the hosted
//      invoice page, a charge receipt page) anywhere but stripe_webhook/, which files the Stripe
//      invoice into finance-docs as the accountant's source record and hands it to nobody;
//   D. the web app links to a Stripe invoice or receipt host;
//   E. (22 Sep 2026) Stripe is asked to make or send a document a person would receive as ours: a checkout
//      sets invoice_creation anywhere but stripe_checkout/ (the reveal fee, whose Stripe invoice is the
//      accountant's filed source record and whose NUMBER our invoice prints), any code sets receipt_email,
//      any code sends a Stripe invoice, or any code but stripe_webhook/ names the filed Stripe PDFs
//      (finance-docs invoices/stripe/), which is how one would be attached to a message.
//
// AND THE PAGES THEMSELVES (22 Sep 2026). This file passed on the day an audit that rendered 37 samples
// found a blank regenerated quotation, English licence lines on Arabic pages, documents with no licence
// line and an off-table navy — none of which source text shows. Run directly, this check therefore also
// runs supabase/functions/pdf_native/every_document_we_issue.test.ts, which renders EVERY document type
// through its real builder with ZZ DEMO data and asserts a body, the letterhead, the licence line in the
// document's language, no English interface word on an Arabic page, 0 dropped characters and the brand
// navy. npm test runs that file on its own (scripts/checks/run.mjs hands every *.test.ts to deno test).
// The written brand rules it enforces are asserted here too: _shared/brand.ts equals the colour rows of
// public.company_brand as scripts/sql/the_company_knows_its_own_brand.sql writes them.
//
// Anchored on CODE SHAPE, not words: comments are removed before matching (apply-discipline §7), and
// C matches a property access (a dot or a bracketed string key), which prose does not contain.
//
// Run: node scripts/checks/every_pdf_we_issue_is_on_our_template.mjs   (exit 1 on any finding)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { DENO_NPM_FLAGS, denoNpmCache } from '../lib/deno_npm.mjs';   // never =auto: it rewrites node_modules (11 Nov 2026)

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const SKIP = new Set(['node_modules', 'vendor', '.next', 'dist']);

/** Source with // line comments and block comments removed (a URL's "//" inside a string survives). */
export function code(src) {
  return String(src).replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:'"`\\])\/\/.*$/gm, '$1');
}

// A static import or a dynamic import() (review of #1796: `await import('https://esm.sh/pdf-lib…')` passed the static form unseen).
const PDF_LIB = /(?:from\s+|\bimport\s*\(\s*)['"`][^'"`]*\b(pdf-lib|jspdf|pdfkit|pdfmake|html-pdf|puppeteer)\b/;
const PDF_MAKE = /\bPDFDocument\s*\.\s*create\s*\(/;
const PDF_RESPONSE = /new\s+Response\s*\([^;]*application\/pdf/;
// A door that answers a person with a PDF it drew through THE renderer (12 Nov 2026, customer_support: my_data_pdf, a
// person's data copy, which pdf_native's internal door may not serve and must not store). It imports renderPdf from
// pdf_native/render.ts and no PDF library, and makes no PDF itself: what it answers with is on the template.
const DRAWS_ON_TEMPLATE = /import\s*\{[^}]*\brenderPdf\b[^}]*\}\s*from\s*['"`]\.\.\/pdf_native\/render\.ts['"`]/;
const STRIPE_DOC = /(\?\.|\.)\s*(invoice_pdf|hosted_invoice_url|receipt_url)\b|\[\s*['"](invoice_pdf|hosted_invoice_url|receipt_url)['"]\s*\]/;
const STRIPE_HOST = /(invoice|pay|receipt)\.stripe\.com/;
const INVOICE_CREATION = /invoice_creation\s*\[\s*enabled\s*\]/;
const RECEIPT_EMAIL_SET = /['"`][^'"`\n]*receipt_email[^'"`\n]*['"`]\s*[,:]|\breceipt_email\s*[:=][^=]/;
const INVOICE_SEND = /\bsend_invoice\b|invoices\/[^;\n]*\/send\b/;
const FILED_STRIPE_PDF = /invoices\/stripe\//;

// THE ONE FILE THAT EDITS A CUSTOMER'S OWN PDF (28 Sep 2026, #1056). pdf_vector_redact.ts rewrites the customer's
// drawing with its identity cut out; that file is the customer's document, never one we issue, so it cannot be on
// our template. It may IMPORT the library to load and save that drawing. It may still never CREATE a PDF or answer
// with one: those two rules apply to it like to every other file (the .test.mjs proves both still fire there).
// The second (review of #1796, 3 Nov 2026): supplier_docs_later.ts cuts a supplier's own scanned company profile to its first pages before
// the reading model sees it (the model bills per page). That copy is the supplier's document, read by a model and handed to nobody, so it is
// held to the same rule: it may load and save the file, and the EDITOR_AUTHORS shapes below still fail it. Since 18 Nov 2026 that cut lives in
// pdf_first_pages.ts, shared with the licence slot, which reads only the first pages of a file longer than any licence (founder ruling 1728).
const EDITS_CUSTOMER_PDF = new Set(['supabase/functions/_shared/pdf_vector_redact.ts', 'supabase/functions/_shared/pdf_first_pages.ts']);
// Review of #1056: in that file the library is in reach, so "creates a PDF" is read wider than PDF_MAKE: the bracket
// form (PDFDocument['create']), any alias of PDFDocument (import ... as, const X = PDFDocument, a destructured
// create), and the calls that author content rather than edit it (addPage, drawText, embedFont and their kin).
const EDITOR_AUTHORS = [
  /\bPDFDocument\s*\[\s*['"`]create['"`]\s*\]/,
  /\bPDFDocument\s+as\s+\w+/,
  /=\s*PDFDocument\b(?!\s*[.[])/,   // any alias, one of many declarators too (const D = PDFDocument, X = 1); a type annotation is not one
  /\{[^}]*\bcreate\b[^}]*\}\s*=\s*PDFDocument\b/,
  /\.\s*(?:addPage|insertPage|copyPages|drawText|drawImage|drawRectangle|drawLine|drawSvgPath|embedFont|embedStandardFont|embedJpg|embedPng|embedPdf|embedPage)\s*\(/,
];

/** Findings for one file. `rel` uses forward slashes. */
export function findingsFor(rel, src) {
  const c = code(src), out = [];
  const inRenderer = rel.startsWith('supabase/functions/pdf_native/');
  if (rel.startsWith('supabase/functions/')) {
    if (!inRenderer && !EDITS_CUSTOMER_PDF.has(rel) && PDF_LIB.test(c)) out.push(`${rel}: imports a PDF-writing library outside pdf_native (A)`);
    if (!inRenderer && PDF_MAKE.test(c)) out.push(`${rel}: creates a PDF document outside pdf_native (A)`);
    else if (EDITS_CUSTOMER_PDF.has(rel) && EDITOR_AUTHORS.some((re) => re.test(c))) out.push(`${rel}: authors PDF content in the customer-drawing editor (A)`);
    const onTemplate = DRAWS_ON_TEMPLATE.test(c) && !PDF_LIB.test(c) && !PDF_MAKE.test(c);
    if (!inRenderer && !onTemplate && PDF_RESPONSE.test(c)) out.push(`${rel}: answers with a PDF body outside pdf_native (B)`);
    if (!rel.startsWith('supabase/functions/stripe_webhook/') && STRIPE_DOC.test(c)) out.push(`${rel}: reads a Stripe-rendered document link (C)`);
    if (!rel.startsWith('supabase/functions/stripe_checkout/') && INVOICE_CREATION.test(c)) out.push(`${rel}: asks Stripe to create an invoice for a checkout (E)`);
    if (RECEIPT_EMAIL_SET.test(c)) out.push(`${rel}: asks Stripe to email its receipt (E)`);
    if (INVOICE_SEND.test(c)) out.push(`${rel}: asks Stripe to send its invoice (E)`);
    if (!rel.startsWith('supabase/functions/stripe_webhook/') && FILED_STRIPE_PDF.test(c)) out.push(`${rel}: names the filed Stripe invoice PDFs, which only the accountant's record may hold (E)`);
  }
  if (rel.startsWith('src/') && STRIPE_HOST.test(c)) out.push(`${rel}: links to a Stripe invoice or receipt host (D)`);
  return out;
}

function* walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (SKIP.has(e.name)) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) yield* walk(p);
    else if (/\.(ts|tsx|js|mjs)$/.test(e.name) && !/\.(test|spec)\.[cm]?[jt]sx?$/.test(e.name) && !/\.fixture\./.test(e.name)) yield p;
  }
}

/** _shared/brand.ts's brand hues against the company_brand colour rows the repository writes. */
export function brandFindings() {
  const brand = fs.readFileSync(path.join(REPO, 'supabase/functions/_shared/brand.ts'), 'utf8');
  const sql = fs.readFileSync(path.join(REPO, 'scripts/sql/the_company_knows_its_own_brand.sql'), 'utf8');
  const out = [];
  for (const [row, key] of [['navy', 'navy'], ['teal', 'teal'], ['teal_light', 'tealLight'], ['teal_deep', 'tealDeep'], ['gold', 'gold']]) {
    const want = (sql.match(new RegExp(`\\('colour\\.${row}',\\s*'colour',\\s*'(#[0-9A-Fa-f]{6})'`)) || [])[1];
    const have = (brand.match(new RegExp(`\\b${key}:\\s*'(#[0-9A-Fa-f]{6})'`)) || [])[1];
    if (!want || !have || want.toUpperCase() !== have.toUpperCase()) out.push(`_shared/brand.ts ${key} ${have} is not company_brand colour.${row} ${want} (brand)`);
  }
  if (/\bC\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*\)\s*,\s*TEAL\b|NAVY\s*=\s*C\(/.test(code(fs.readFileSync(path.join(REPO, 'supabase/functions/pdf_native/render.ts'), 'utf8')))) {
    out.push('pdf_native/render.ts draws a brand hue from its own literal, not from _shared/brand.ts (brand)');
  }
  return out;
}

export function scan() {
  const out = [...brandFindings()];
  for (const root of ['supabase/functions', 'src']) {
    for (const f of walk(path.join(REPO, root))) {
      const rel = path.relative(REPO, f).split(path.sep).join('/');
      out.push(...findingsFor(rel, fs.readFileSync(f, 'utf8')));
    }
  }
  return out;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const f = scan();
  for (const x of f) console.log('FAIL ' + x);
  console.log(f.length ? `${f.length} PDF path(s) off the QuotesDone template` : 'every PDF path goes through the QuotesDone template (pdf_native)');
  // The pages. A missing deno is a failure, never a skip (the rule scripts/checks/run.mjs keeps).
  const r = spawnSync('deno', ['test', ...DENO_NPM_FLAGS, `--allow-read=${REPO},${denoNpmCache()}`, 'supabase/functions/pdf_native/every_document_we_issue.test.ts'],
    { cwd: REPO, stdio: 'inherit', shell: process.platform === 'win32' });
  const pagesOk = r.status === 0;
  if (!pagesOk) console.log('FAIL the rendered documents are not all on the template (every_document_we_issue.test.ts)' + (r.error ? ': ' + r.error.message : ''));
  process.exit(f.length || !pagesOk ? 1 : 0);
}
